728: void get_xi(const int nsd, consts::ElementType eType, const int eNoN, const Array<double>& xl, const Vector<double>& xp, 
729:     Vector<double>& xi, bool& flag)
730: {
731:   static const int MAXITR = 5;
732:   static const double RTOL = 1.E-6;
733:   static const double ATOL = 1.E-12;
734: 
735:   Vector<double> xK(nsd);  
736:   Vector<double> rK(nsd);
737:   Vector<double> N(eNoN);
738:   Array<double> Nxi(nsd,eNoN);
739: 
740:   int itr = 0;
741:   auto xiK = xi;
742:   double eps = std::numeric_limits<double>::epsilon();
743:   bool l1, l2, l3;
744: 
745:   while (true) { 
746:      itr = itr + 1;
747:      nn::get_gnn(nsd, eType, eNoN, xiK, N, Nxi);
748:      xK = 0.0;
749: 
750:      for (int i = 0; i < nsd; i++) {
751:         for (int a = 0; a < eNoN; a++) {
752:            xK(i) = xK(i) + N(a)*xl(i,a);
753:         }
754:         rK(i) = xK(i) - xp(i);
755:      }
756: 
757:      double rmsA = 0.0;
758:      double rmsR = 0.0;
759: 
760:      for (int i = 0; i < nsd; i++) {
761:         rmsA = rmsA + pow(rK(i), 2.0);
762:         rmsR = rmsR + pow(rK(i) / (xK(i)+eps), 2.0);
763:      }
764:      rmsA = sqrt(rmsA/static_cast<double>(nsd));
765:      rmsR = sqrt(rmsR/static_cast<double>(nsd));
766: 
767:      l1 = itr > MAXITR;
768:      l2 = rmsA <= ATOL;
769:      l3 = rmsR <= RTOL;
770:      if (l1 || l2 || l3) {
771:        break;
772:      }
773: 
774:      Array<double> Am(nsd, nsd);
775: 
776:      for (int i = 0; i < nsd; i++) {
777:        for (int j = 0; j < nsd; j++) {
778:          for (int a = 0; a < eNoN; a++) {
779:            Am(i,j) = Am(i,j) + xl(i,a)*Nxi(j,a);
780:          }
781:        }
782:      }
783: 
784:      Am  = mat_fun::mat_inv(Am, nsd);
785:      rK  = mat_fun::mat_mul(Am, rK);
786:      xiK = xiK - rK;
787:   }
788: 
789:   // Newton's method converges
790:   if (l2 || l3) {
791:      flag = true; 
792: 
793:   // Newton's method failed to converge
794:   } else { 
795:     flag = false; 
796:   }
797: 
798:   xi = xiK;
799: }
